    { 名称: '屎肠球菌', id: 'enterococcus-faecium', 相似点: '同属肠球菌，胆汁七叶苷阳性、PYR阳性。', 鉴别: '铅黄肠球菌有动力、产黄色素、万古霉素固有低度耐药(vanC)；屎肠球菌无动力、无色素，万古耐药则为获得性vanA/vanB高度耐药。' }
