    { 名称: '阴沟肠杆菌', id: 'enterobacter-cloacae', 相似点: '同为可诱导 AmpC、三代头孢治疗中易耐药的机会致病肠杆菌', 鉴别: 'H₂S：弗劳地柠檬酸杆菌(+)、阴沟肠杆菌(−)；脲酶：柠檬酸杆菌弱(+)、阴沟弱/−。' },
    { 名称: '克氏柠檬酸杆菌', id: 'citrobacter-koseri', 相似点: '同属柠檬酸杆菌', 鉴别: '吲哚与 H₂S：弗劳地(吲哚− / H₂S+)、克氏(吲哚+ / H₂S−)。' }
