    { 名称: '肺炎克雷伯菌', id: 'klebsiella-pneumoniae', 相似点: 'VP(+)、可产黏液菌落', 鉴别: '沙雷菌有动力、DNase(+)、鸟氨酸脱羧酶(+);克雷伯无动力、DNase(−)、有厚荚膜、脲酶(+)。' }
