    { 名称: '铜绿假单胞菌', id: 'pseudomonas-aeruginosa', 相似点: '均为专性需氧、氧化酶阳性、有动力的非发酵革兰阴性杆菌', 鉴别: '铜绿产绿脓素、42℃旺盛生长、氧化分解葡萄糖产酸、精氨酸双水解酶阳性；粪产碱杆菌不产色素、糖类完全不氧化(产碱)、硝酸盐不还原为亚硝酸盐' }
